@JvmStatic
fun craftShield(player: Player): Boolean {
    if (stage(player) !in FremennikIslesState.DECREE_ISSUED..FremennikIslesState.RITES_READY || player.skills.getLevelForXp(Skills.WOODCUTTING) < 56 || !inventoryHas(player, FremennikIslesIds.HAMMER)) return false
    if (hasAnywhere(player, FremennikIslesIds.FREMENNIK_ROUND_SHIELD)) return true
    if (!consume(player, FremennikIslesIds.ARCTIC_PINE_LOGS to 2, FremennikIslesIds.BRONZE_NAIL to 1, FremennikIslesIds.ROPE to 1)) return false
    if (!grantUnique(player, FremennikIslesIds.FREMENNIK_ROUND_SHIELD)) {
        player.inventory.addItem(FremennikIslesIds.ARCTIC_PINE_LOGS, 2)
        player.inventory.addItem(FremennikIslesIds.BRONZE_NAIL, 1)
        player.inventory.addItem(FremennikIslesIds.ROPE, 1)
        return false
    }
    player.skills.addXp(Skills.CRAFTING, 34.0)
    return true
}

@JvmStatic
fun fitEmeraldToSickle(player: Player): Boolean {
    if (stage(player) !in FLAIL_CRAFTED..ORNATE_KEY ||
        !hasTool(player, LegacyOfSeergazeIds.CHISEL)
    ) return false
    return exchange(
        player,
        arrayOf(
            Item(LegacyOfSeergazeIds.BLESSED_SICKLE),
            Item(LegacyOfSeergazeIds.CUT_EMERALD),
        ),
        arrayOf(Item(LegacyOfSeergazeIds.SILVER_SICKLE_EMERALD)),
    )
}

@JvmStatic
fun enchantEmeraldSickle(player: Player): Boolean {
    if (stage(player) !in FLAIL_CRAFTED..ORNATE_KEY ||
        player.skills.getLevelForXp(Skills.MAGIC) < 49
    ) return false
    return exchange(
        player,
        arrayOf(
            Item(LegacyOfSeergazeIds.SILVER_SICKLE_EMERALD),
            Item(LegacyOfSeergazeIds.COSMIC_RUNE),
            Item(LegacyOfSeergazeIds.AIR_RUNE, 3),
        ),
        arrayOf(Item(LegacyOfSeergazeIds.ENCHANTED_SICKLE_EMERALD)),
    )
}

def _can_start_crafting_action(ctx: RuntimeActionContext) -> bool:
    target = ctx.player_data.get("current_craft", "form_pot_unfired")
    return not crafting_target_locked_reasons_pure(
        ctx.player_data,
        target,
        CRAFTING_DATA,
        QUEST_UNLOCK_RULES,
    )

suspend fun craftSilver(
    task: QueueTask,
    player: Player,
    data: SilverData,
    amount: Int,
) {
    val inventory = player.inventory

    repeat(amount) {
        if (!canCraft(task, data)) {
            player.animate(Anims.RESET)
            return
        }
        player.animate(Anims.SMELT_FURNACE)
        player.playSound(Sfx.FURNACE)
        task.wait(3)
        if (!inventory.remove(Items.SILVER_BAR, assureFullRemoval = true).hasSucceeded()) {
            return
        }
        if (data.extraItems != null) {
            data.extraItems.forEach {
                if (!inventory.remove(item = it, assureFullRemoval = true).hasSucceeded()) {
                    return
                }
            }
        }
        inventory.add(data.resultItem, assureFullInsertion = true)
        player.addXp(Skills.CRAFTING, data.experience)
        task.wait(2)
    }
}

/**
 * TODO Add checking for quest-specific items for quest progress
 */
private suspend fun canCraft(
    task: QueueTask,
    data: SilverData,
): Boolean {
    val player = task.player
    val inventory = player.inventory
    val resultName =
        player.world.definitions
            .get(ItemDef::class.java, data.resultItem.id)
            .name
            .lowercase()

    if (!inventory.contains(Items.SILVER_BAR)) {
        return false
    }

    if (data.extraItems != null) {
        data.extraItems.forEach {
            if (!inventory.contains(it)) {
                return false
            }
        }
    }

    if (!inventory.contains(data.mould.id)) {
        return false
    }
